55	const PROCESSING_FEE = 5;
56	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const COMPONENT_TYPES = ["rune", "moonstone"];
68	const BLOCK_SIZE = 3;
69	const BLOCK_BASE_PREMIUM = 60;
70	const CURSE_SURCHARGE_RATE = 0.5;
71	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
72	const HIGH_ENCHANTMENT_THRESHOLD = 5;
73	const LOYALTY_DISCOUNT_RATE = 0.2;
74	const LOYALTY_YEARS_THRESHOLD = 2;
75	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
76	
77	const sum = (amounts: number[]): number => amounts.reduce((total, a) => total + a, 0);
78	
79	/** Rounds to whole G in the MHPCO's favour. */
80	const roundUpToWholeG = (amount: number): number => Math.ceil(amount);
81	
82	const groupByType = (items: Item[]): Map<string, Item[]> => {
83	  const groups = new Map<string, Item[]>();
84	  for (const item of items) {
85	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
86	  }
87	  return groups;
88	};
89	
90	const basePremiumForItem = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
91	
92	/**
93	 * Components are priced per group of alike items, because a building block of
94	 * exactly 3 alike components earns a special rate. Main items price per item.
95	 */
96	const basePremiumForGroup = (type: string, group: Item[]): number => {
97	  if (COMPONENT_TYPES.includes(type) && group.length === BLOCK_SIZE) {
98	    return BLOCK_BASE_PREMIUM;
99	  }
100	  return sum(group.map(basePremiumForItem));
101	};
102	
103	/** Item-specific surcharges apply to the affected item's own base premium. */
104	const ITEM_SURCHARGES: { applies: (item: Item) => boolean; rate: number }[] = [
105	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
106	  {
107	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
108	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
109	  },
110	];
111	
112	const itemSurchargeTotalFor = (item: Item): number =>
113	  sum(
114	    ITEM_SURCHARGES.filter(({ applies }) => applies(item)).map(
115	      ({ rate }) => basePremiumForItem(item) * rate,
116	    ),
117	  );
118	
119	/**
120	 * Policy-wide modifiers are rates on the UNMODIFIED policy base premium — not
121	 * on the running total, and not on the item surcharges. Charging 10 % of a
122	 * cursed sword's 150 G rather than of its 100 G base is the mistake this
123	 * indirection exists to prevent.
124	 */
125	const policyModifierTotalFor = (policyBasePremium: number, rates: number[]): number =>
126	  sum(rates.map((rate) => policyBasePremium * rate));
127	
128	/**
129	 * Discounts are negative rates, so the policy modifiers stay a single sum.
130	 *
131	 * The initial assessment surcharge is deliberately NOT in here: it is charged on
132	 * every policy, including a long-standing customer's follow-up contract, so it
133	 * depends on nothing about the customer.
134	 */
135	const customerModifierRatesFor = (customer: Customer): number[] =>
136	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD ? [-LOYALTY_DISCOUNT_RATE] : [];
137	
138	/** The follow-up discount depends on scenario position, not on the customer. */
139	const policyModifierRatesFor = (customer: Customer, isFollowUpContract: boolean): number[] => [
140	  INITIAL_ASSESSMENT_SURCHARGE_RATE,
141	  ...customerModifierRatesFor(customer),
142	  ...(isFollowUpContract ? [-FOLLOW_UP_DISCOUNT_RATE] : []),
143	];
144	
145	const quotePremium = (
146	  items: Item[],
147	  customer: Customer,
148	  isFollowUpContract: boolean,
149	): number => {
150	  const policyBasePremium = sum(
151	    [...groupByType(items)].map(([type, group]) => basePremiumForGroup(type, group)),
152	  );
153	  const itemSurchargeTotal = sum(items.map(itemSurchargeTotalFor));
154	  const policyModifierTotal = policyModifierTotalFor(
155	    policyBasePremium,
156	    policyModifierRatesFor(customer, isFollowUpContract),
157	  );
158	  return roundUpToWholeG(
159	    policyBasePremium + itemSurchargeTotal + policyModifierTotal + PROCESSING_FEE,
160	  );
161	};
162	
163	export const runScenario = (scenario: Scenario): ScenarioResult => {
164	  const results: StepResult[] = [];
165	  let quotesSoFar = 0;
166	
167	  for (const step of scenario.steps) {
168	    const isFollowUpContract = quotesSoFar > 0;
169	    quotesSoFar += 1;
170	    results.push({
171	      premium: quotePremium((step as QuoteStep).items, scenario.customer, isFollowUpContract),
172	    });
173	  }
174	
175	  return { results };
176	};
