export const runScenario = (scenario: Scenario): ScenarioResult => {
  const results: StepResult[] = [];
  /** A quote is a follow-up contract once any earlier step has quoted one. */
  const quotedPolicies: QuoteStep[] = [];

  for (const step of scenario.steps) {
    const quoteStep = step as QuoteStep;
    results.push({
      premium: quotePremium(quoteStep.items, {
        customer: scenario.customer,
        isFollowUpContract: quotedPolicies.length > 0,
      }),
    });
    quotedPolicies.push(quoteStep);
  }

  return { results };
};
